### Summary

Add `is_json_response` hook on `Flask` so subclasses can extend which return types get serialized as JSON, e.g. `msgspec.Struct` or `pydantic.BaseModel`. The default implementation matches `dict` and `list` — same behavior as before.

### Usage Example

```python
import typing as t

import msgspec
from flask import Flask as _Flask, Response
from flask.json.provider import DefaultJSONProvider


class User(msgspec.Struct):
    name: str
    age: int


class MsgspecJSONProvider(DefaultJSONProvider):
    # dumps and loads omitted

    def response(self, *args: t.Any, **kwargs: t.Any) -> Response:
        obj = self._prepare_response_obj(args, kwargs)
        data: bytes = msgspec.json.encode(obj)
        return self._app.response_class(data, mimetype=self.mimetype)


class Flask(_Flask):
    json_provider_class = MsgspecJSONProvider

    @staticmethod
    def is_json_response(rv: object) -> bool:
        return isinstance(rv, (dict, list, msgspec.Struct))


app = Flask(__name__)


@app.get("/user")
def get_user() -> User:
    return User(name="Douglas", age=42)
```

Sentinel is an implementation detail that is not intentionally exposed. However, it is in the context params during a callback: sentinel_in_callback.py

```
import click

def _validate(ctx, param, value):

    you_sentinel = ctx.params.get("you")
    you_too_sentinel = ctx.params.get("you_too")
    print(f"you: {you_sentinel}")
    print(f"you_too: {you_too_sentinel}")
    print(f"param: {param}")
    print(f"value: {value}")
    return value

@click.group()
def basic():
    pass

@basic.command()
@click.argument('you', required=False)
@click.option('--you-too', )
@click.option('--yall', callback=_validate)
@click.pass_context
def hello(ctx, you, you_too, yall):
    click.echo('Hello World!')

if __name__ == '__main__':
    basic()
    # python -m sentinel_in_callback hello
``` 

``` 
> python -m sentinel_in_callback hello
you: Sentinel.UNSET
you_too: Sentinel.UNSET
param: <Option yall>
value: None
Hello World!
```

